    public <Q, R> List<R> queryList(Q query, Class<R> type) {
        try {
            return queryGateway.query(query, ResponseTypes.multipleInstancesOf(type)).get(20, TimeUnit.SECONDS);
        } catch (Exception e) {
            throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "query failed", e);
        }
    }

    public static void require(boolean condition, String message) {
        if (!condition) {
            throw new BadRequest(message);
        }
    }
}

